#include <benchmark/benchmark.h>
#include <vector>
#include <chrono>

// This header is generated by your build system from the compiled MLIR object
extern "C" void _mlir_ciface_matmul_optimized(float* A, float* B, float* C);
extern "C" void _mlir_ciface_matmul_baseline(float* A, float* B, float* C);

static void BM_Matmul(benchmark::State& state) {
    int N = state.range(0);
    std::vector<float> A(N * N, 1.0f), B(N * N, 2.0f), C(N * N, 0.0f);
    
    for (auto _ : state) {
        // We measure only the kernel execution
        _mlir_ciface_matmul_optimized(A.data(), B.data(), C.data());
        benchmark::DoNotOptimize(C);
    }
    state.SetComplexityN(N);
}
BENCHMARK(BM_Matmul)->RangeMultiplier(2)->Range(64, 1024);
BENCHMARK_MAIN();